下面 C++ 代码执行后的输出是？（）

```cpp
int n, a, m, i;
n = 3, a = 5;
m = (a - 1) * 2;
for (i = 0; i < n - 1; i++)
    m = (m - 1) * 2;
cout << m;
```

下面 C++ 代码执行后的输出是？（）

```cpp
int n, i, result;
n = 81;
i = 1, result = 1;
while (i * i <= n) {
    if (n % (i * i) == 0)
        result = i * i;
    i += 1;
}
cout << result;
```

下面 C++ 代码执行后的输出是？（）

```cpp
int s, t, ans;
s = 2, t = 10;
ans = 0;
while (s != t) {
    if (t % 2 == 0 && t / 2 >= s)
        t /= 2;
    else
        t -= 1;
    ans += 1;
}
cout << ans;
```

下面 C++ 代码执行后的输出是？（）

```cpp
int n, masks, days, cur;
n = 17, masks = 10, days = 0;
cur = 2;
while (masks != n) {
    if (cur == 0 || cur == 1)
        masks += 7;
    masks -= 1;
    days += 1;
    cur = (cur + 1) % 7;
}
cout << days;
```

